INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (60,'Yara Pink EDP 100 ML','🌸 عطر لطافة هو عطر نسائي راقٍ، يتميز برائحة لطيفة وساحرة تدوم طويلاً. مثالي لأي يوم أو مناسبة خاصة، فهو يضفي أناقةً ورائحةً فريدة. ✨',68.00,'1784756356_yaralatafa.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (61,'Yara Candy','عطرٌ مرحٌ للغاية، أنثويٌّ بامتياز، يفتتح بنفحات فاكهية منعشة، ويتوسطه حلاوةٌ تشبه الحلوى، وينتهي بقاعدةٍ كريميةٍ ناعمة. يمنحك إحساساً بالوردي، والمرح، والجاذبية، والذوق الرفيع، مع لمسةٍ دافئةٍ من الفانيليا والمسك.',68.00,'1784756578_yaracandy.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (62,'Yara Elixir EDP 100ML','عطر زهري فاكهي حلو ودسم، يجمع بين نفحات الفراولة والمارشميلو، والكشمش الأسود، وزهر البرتقال، والياسمين، والفانيليا، والكراميل، والعنبر، والمسك. عطر ناعم، مرح، وأنثوي، بدفء ناعم يشبه الحلوى.',68.00,'1784756881_Yara Elixir.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (63,'Yara Moi EDP 100ML','عطر من لطافة يقدم مزيجاً كريمياً من الأزهار، يتميز بتوازن دقيق ورقيّ. مزيج من نفحات الفواكه والزهور البيضاء ولمسات كريمية يخلق تجربة أنيقة وساحرة تجعلك تُقدّرين العطور الأنثوية الراقية.',65.00,'1784757190_yaramoilataf.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (64,'Amiret el arab rouge EDP 100ML','أميرة العرب: عطر أنثوي ساحر يجسد الفخامة والرقي، بتركيبة آسرة تدوم طويلًا وتمنحكِ حضورًا ملكيًا لا يُنسى.',52.00,'1784757741_amiret larab rouge.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (65,'Amiret el arab rose EDP 100ML','🌹✨ أميرة العرب روز ✨🌹\r\nعطر أنثوي راقٍ يجمع بين سحر الورد 🌸 ولمسات الفاكهة المنعشة 🍓، ليمنحكِ إطلالة أنيقة وحضورًا جذابًا يدوم طوال اليوم 💖👑',52.00,'1784758440_ameeretarabrose.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (66,'Amiret el arab suger grown EDP 100 ML','🍭👑 أميرة العرب Suger Grown 👑🍭\r\nعطر أنثوي فاخر بنفحات الكمثرى 🍐 والبرتقال المُحلّى 🍊 وقلبٍ من الياسمين 🌸 وغزل البنات 🍬، ينساب على قاعدة دافئة من الفانيليا ✨ ليمنحكِ حضورًا ناعمًا وساحرًا يدوم طويلًا. 💖🌷',52.00,'1784759082_Ameerat Al Arab Sugar Crown.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (67,'Ameer el arab noir EDP 100 ML','عطر رجالي ساحر بطابع فاخر وجذاب، يجمع بين القوة والرقي ليمنحك إطلالة مميزة وحضورًا لا يُنسى في كل مناسبة. ✨🔥',52.00,'1784759526_ameer larab noir.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (68,'بديل العود Amethyst','💜✨ بديع العود أماثيستAmethyst  ✨💜\r\nعطر فاخر للجنسين يجمع بين رقي الورد التركي 🌹 وسحر العود الشرقي 🪵 ولمسات الفانيليا الدافئة 🍦، ليمنحك حضورًا أنيقًا وجذابًا يدوم لساعات طويلة. مزيج ساحر من الفخامة والدفء يترك أثرًا لا يُنسى أينما ذهبت. 👑💫',72.00,'1784889432_بديل العودamethyst.jpeg',8,20);
