INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (71,' بديع العود  Sublime','❤️✨ بديع العود سوبلايم Sublime ✨❤️\r\nعطر فاخر للجنسين يمزج بين انتعاش التفاح والليتشي 🍎🍓 ورقة الورد 🌹، مع قلبٍ أنيق من البرقوق والياسمين ✨، ليستقر على قاعدة دافئة من الفانيليا والمسك والباتشولي 🤍. عطر عصري جذاب يمنحك حضورًا راقيًا ولمسة لا تُنسى طوال اليوم',72.00,'badeealoudsublime.png',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (72,'بديع العود Noble Blush','🌸✨ بديع العود نوبل بلاش Noble Blush ✨🌸\r\nعطر أنيق وناعم يضفي على إطلالتك لمسة من الرقي والجاذبية 💖، بعبير منعش ومريح يمنحك إحساسًا بالثقة والانتعاش طوال اليوم. الخيار المثالي لكل من تبحث عن الأناقة الهادئة والحضور المميز. 👑🌷\r\n',72.00,'badee aloud nobel bluch.png',8,20);
