INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (75,'Mayar Cherry Intense ✨🍒EDP','🍒 Mayar Cherry Intense ✨🍒\r\nعطر أنثوي جريء وساحر يبدأ بنفحات الكرز والتوت الشهية 🍒🍓، يتألق بلمسات زهرية ناعمة 🌸، ويستقر على قاعدة كريمية دافئة من الفانيليا 🤍. عطر غني وجذاب يترك انطباعًا لا يُنسى ويمنحكِ حضورًا آسرًا في كل مناسبة. 💖👑🔥',65.00,'1784892156_mayar_chery_intense.png',8,20);
