INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (77,'Exclaire 🍯✨ Creamy Vanilla, Caramel & Whipped Cream Fragrance','حلوة، كريمية، وآسرة للغاية ✨ يمزج عطر لطافة إكلير بين الفانيليا الغنية، والكراميل الدافئ، ونفحات الأزهار الرقيقة، ليمنحكِ رائحةً تُشبه أفخر حلوى تذوقتها على الإطلاق. إذا كنتِ من مُحبات العطور الدافئة والناعمة، فهذا العطر لا غنى عنه في مجموعتكِ. 🍯🤍',65.00,'1784913134_eclaire.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (78,'Fakhar Lattafa  Gold Extrait Perfume – Premium Golden Luxury Fragrance ✨💛','💛👑 فخر اللطافة Gold Extrait 👑💛\r\nعطر فاخر للجنسين يجمع بين النفحات الزهرية والعنبرية والخشبية في تركيبة أنيقة تدوم طويلًا. ✨\r\n💎 يمنحك حضورًا راقيًا وجاذبية استثنائية تناسب جميع المناسبات.',62.00,'1784913389_Lattafa_Fakhar_Gold.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (79,' فخر لطافة Silver  ✨🖤','🖤✨ فخر لطافة العربي ✨🖤\r\nعطر فاخر للجنسين يجمع بين الأصالة العربية والأناقة العصرية، بتركيبة آسرة تدوم طويلًا وتمنحك حضورًا مميزًا في كل مناسبة. 👑🌙\r\n🔥 رائحة جذابة تنبض بالفخامة وتترك أثرًا لا يُنسى أينما ذهبت.',62.00,'1784913605_FAKHAR_LATAFA_silver.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (80,'انا الابيض EDP 100ml','🤍✨ أنا الأبيض من لطافة ✨🤍\r\nعطر فاخر للجنسين يجمع بين الانتعاش والفخامة، بنفحات فاكهية ناعمة ولمسات من الفانيليا والمسك والعنبر تمنحك حضورًا أنيقًا يدوم طوال اليوم. 🍐🍊🤍\r\n💫 رائحة جذابة وعصرية تترك أثرًا لا يُنسى في كل مناسبة. 🌟',55.00,'1784913880_enalabyadh.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (81,'Ana Abiyedh Scarlet EDP','🍒✨ أنا أبيض سكارليت Ana Abiyedh Scarlet ✨🍒\r\n\r\n🌹 نفحات الكرز الأسود والفلفل الوردي تلتقي مع الورد الأبيض والفانيليا في تركيبة أنثوية ساحرة تدوم طويلًا. 🤍\r\n💖 عطر فاخر يجمع بين الحلاوة والرقي، ليمنحكِ حضورًا جذابًا وأثرًا لا يُنسى في كل مناسبة. 👑✨',55.00,'1784914194_Ana_Abiyedh_Scarlet.png',8,20);
