INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (224,'Bella – Franck Olivier','🌸 **Bella – Franck Olivier ** ✨  \r\n💖 عطر أنثوي ناعم وجذاب، يجمع بين النفحات الزهرية والفاكهية مع لمسات حلوة ومنعشة، ليمنحك إحساسًا بالرقة والأناقة والجاذبية في كل مناسبة.',79.00,'1792843945_bella.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (225,'Bella Rose – Franck Olivier','🌹 **Bella Rose – Franck Olivier** ✨  \r\n💗 عطر أنثوي رقيق وأنيق، يجمع بين نفحات الورد الزهرية واللمسات الفاكهية الناعمة، ليمنحك إحساسًا بالأنوثة والجاذبية مع لمسة رومانسية ساحرة.',79.00,'1792844024_bella_rose.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (226,'Eau de Passion Men – Franck Olivier','✨ **Eau de Passion Men – Franck Olivier  🔥**\r\n🖤 عطر رجالي أنيق من **Franck Olivier**، يجمع بين النفحات المنعشة والعطرية مع لمسات خشبية جذابة، ليمنحك حضورًا راقيًا وثقةً مميزة في كل مناسبة.',79.00,'1792844147_eau_de_passion_men.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (227,'Sun Java Rose Oud – Franck Olivier','🌹 Sun Java Rose Oud – Franck Olivier ✨\r\n🖤 عطر أنيق وجذاب يجمع بين نفحات الورد الفاخرة والعود الدافئ، ليمنحك رائحة شرقية راقية ولمسة من الغموض والفخامة تناسب مختلف المناسبات.',79.00,'1792844238_sun_java_rose_oud.jpeg',8,29);
