INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (229,'Franck Olivier Nature','🌿 **Nature – Franck Olivier**✨\r\n🌸 عطر أنيق ومنعش يجمع بين النفحات الزهرية والفاكهية مع لمسات طبيعية ناعمة، ليمنحك إحساسًا بالانتعاش والرقي والجاذبية في كل مناسبة.',79.00,'1792844557_nature_frunk_olivier.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (230,'Sun Java White – Franck Olivier','🤍 **Sun Java White – Franck Olivier  ✨**\r\n🌸 عطر أنثوي ناعم وأنيق، يجمع بين النفحات الزهرية والفواكه المنعشة مع لمسات دافئة وحلوة، ليمنحك إحساسًا بالرقة والانتعاش والجاذبية في كل مناسبة.',79.00,'1792844653_sun_java_white.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (231,'Sun Java Black – Franck Olivier','🖤 **Sun Java Black – Franck Olivier** ✨  \r\n🌙 عطر أنيق وجذّاب بلمسات دافئة وحسية، يمنحك حضورًا مميزًا وفخامة تدوم، مثالي لمحبي العطور الغامضة والراقية في كل مناسبة.',79.00,'1792844813_sun_java_black.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (232,'Sun Java Intense – Franck Olivier','🔥 **Sun Java Intense – Franck Olivier** ✨  \r\n🌹 عطر جذّاب بلمسات دافئة وحلوة، يجمع بين الأناقة والقوة ليمنحك حضورًا مميزًا وجاذبية لافتة، مثالي لمحبي العطور الفاخرة والمميزة.',75.00,'1792845013_Sun_Java_Intense.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (233,'Sun Royal Oud – Franck Olivier','👑 **Sun Royal Oud – Franck Olivier** ✨  \r\n🪵 عطر فاخر وأنيق، يجمع بين دفء العود واللمسات الشرقية الغنية ليمنحك حضورًا قويًا وهيبة وجاذبية مميزة، مثالي لعشاق العطور الراقية والفخمة.',75.00,'1792845080_Sun_royal_oud.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (234,'Sun Java Blue – Franck Olivier 75ml','💙 **Sun Java Blue – Franck Olivier** ✨  \r\n🌊 عطر منعش وأنيق بلمسات عطرية جذّابة، يمنحك إحساسًا بالحيوية والانتعاش مع حضور مميز يناسب كل الأوقات، مثالي لمحبي العطور العصرية والمنعشة.',75.00,'1792845189_sun_java_blue.jpeg',8,29);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (235,'Teriaq – Lattafa','🖤 **Teriaq – Lattafa** ✨  \r\n🍯 عطر شرقي فاخر يجمع بين الحلاوة الدافئة والتوابل الغنية مع لمسات عطرية جذّابة، ليمنحك حضورًا قويًا وفخمًا ولمسة من الغموض والأناقة في كل مناسبة. 👑',95.00,'1792846644_TERIAQ.png',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (236,'Teriaq Intense – Lattafa','🔥 **Teriaq Intense – Lattafa** 🖤  \r\n🍒 عطر شرقي غني وجريء، يمزج بين النفحات الحلوة والتوابل الدافئة ولمسات عميقة وفاخرة، ليمنحك حضورًا قويًا وجاذبية لا تُقاوم. 👑✨',95.00,'1792846800_teriaq_intense.png',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (237,'Vanilla Voyage EDP 100ml','🍦 **Vanilla Voyage – Maison Asrar EDP 100ml** ✨  \r\n🤍 رحلة عطرية في عالم الفانيليا الحلوة والكريمية، بلمسات دافئة وناعمة تمنحك إحساسًا بالراحة والفخامة والجاذبية. عطر مثالي لعشاق الروائح الحلوة والساحرة! 🍯💕',85.00,'1794346651_Vanilla_voyage_maison_asrar_edp_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (238,'Eternal Vanille EDP 100ml','🍦 **Eternal Vanille – Lattafa EDP 100ml** ✨  \r\n🤎 عطر دافئ وحلو بطابع Gourmand، يجمع بين نفحات الفانيليا الكريمية واللمسات السكرية الناعمة، ليمنحك إحساسًا بالدفء والأنوثة والجاذبية. رائحة ساحرة لعشاق الفانيليا! 🍮💕',95.00,'1794346754_eternal_vanille_edp_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (239,'Eternal Oud EDP 100ml','👑 **Eternal Oud – Lattafa EDP 100ml** ✨  \r\n🪵 عطر شرقي فاخر يجمع بين دفء العنبر والعود ولمسات حلوة وغنية، ليمنحك رائحة عميقة وأنيقة مع حضور قوي وفخامة تدوم. مثالي لعشاق العطور الشرقية الراقية. 🖤',88.00,'1794346954_Lattafa_Eternal_oud_edp_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (240,'Marshmallow Blush – Maison Paris Corner 100ml EDP','🩷 **Marshmallow Blush – Maison Paris Corner 100ml** ✨  \r\n🍓 عطر حلو وأنثوي بطابع Gourmand، يمزج بين نفحات المارشميلو الناعمة والحلاوة الكريمية مع لمسات فاكهية جذّابة، مستوحى من أجواء Kayali Marshmallow. رائحة حالمة كالحلوى لعشاق العطور السكرية! 🍬💕',95.00,'1794347042_Marshmelow_bleush_maison_paris_corner_dupe_kayali_marshmelow_edp_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (241,'Lamset Harir Chocolate Dubai My Perfume 100ml','🍫 **Lamset Harir – Chocolate Dubai – My Perfume 100ml** ✨  \r\n🤎 عطر Gourmand غني ولذيذ، يجمع بين حلاوة الشوكولاتة ولمسات المارشميلو الكريمية، مستوحى من أجواء Kayali Marshmallow، ليمنحك رائحة حلوة ودافئة تشبه الحلويات الفاخرة! 🍬💕',48.00,'1794347107_Lamset_harir_chokolat_dubai_dupe_kayali_marshmelow_edp_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (242,'Lamset Harir 100ml – My Parfume','🌸 **Lamset Harir 100ml – My Perfume** ✨  \r\n🤍 عطر ناعم وأنيق، يجمع بين الرقة والأنوثة بلمسات عطرية جذّابة، ليمنحك إحساسًا بالفخامة والنعومة وحضورًا راقيًا في كل مناسبة.',48.00,'1794347183_Lamset_harir_my_parfume_100_ml.jpeg',8,20);
INSERT INTO `produits` (`id`,`nom`,`description`,`prix`,`image`,`categorie_id`,`marque_id`) VALUES (243,'Alfares – My Parfum EDP 100ml','🐎 **Alfares – My Perfume** ✨  \r\n🌿 عطر أنيق وجذّاب بلمسات عطرية مميزة، يمنحك إحساسًا بالانتعاش والثقة مع حضور راقٍ يناسب مختلف الأوقات والمناسبات.',48.00,'1794347239_Alfares_my_parfume.jpeg',8,20);
